import {mkdtemp,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join} from 'node:path';import {createServer} from 'node:net';import {spawn} from 'node:child_process';
import {readFile,lstat,realpath} from 'node:fs/promises';import {createHash} from 'node:crypto';import {pathToFileURL} from 'node:url';
import {createServer as httpServer} from 'node:http';
import {resolve,sep} from 'node:path';
const pagesMode=process.argv[3]==='pages';
const packageDir=process.argv[2]?resolve(process.argv[2]):null,moduleRoot=packageDir?resolve(packageDir,'pc-agent-runtime'):process.cwd();
if(packageDir){const manifest=JSON.parse(await readFile(join(packageDir,'package-manifest.json'),'utf8'));if(manifest.packageId!=='jarvis-pc-agent-windows-service')throw Error('FIXTURE_PACKAGE_INVALID');
 for(const [name,entry] of Object.entries(manifest.fileIntegrity).filter(([name])=>name.startsWith('pc-agent-runtime/'))){const path=resolve(packageDir,name),info=await lstat(path);if(!path.startsWith(packageDir+sep)||!info.isFile()||info.isSymbolicLink()||info.size>8388608||resolve(await realpath(path)).toLowerCase()!==path.toLowerCase()||createHash('sha256').update(await readFile(path)).digest('hex')!==entry.sha256)throw Error('FIXTURE_PACKAGE_INTEGRITY');}}
const {IntegrationConnectorRegistry}=await import(pathToFileURL(resolve(moduleRoot,'packages/core/src/personal-operations/integration-security.js')));
const {createConfiguredCoreServiceRuntime}=await import(pathToFileURL(resolve(moduleRoot,'scripts/core-service-runtime.mjs')));
const root=await mkdtemp(join(tmpdir(),'jarvis-ms-mission-ui-'));
const record={connectionId:'synthetic-ui',connectorId:'jarvis-outlook-read',authMethod:'oauth2',status:'credentials-stored-unverified',scopes:['Mail.ReadBasic']};let calls=0,graphCalls=0;
const vault={save(){throw Error('FIXTURE_SECRET_WRITE_FORBIDDEN');},list:()=>[{...record,scopes:[...record.scopes]}],credentialRevision:()=> 'synthetic-ui-v1',withCredentials:async(id,run)=>run({tenantId:'common',clientId:'synthetic',clientSecret:'synthetic-secret',refreshToken:'synthetic-refresh'},record)};
const service=await createConfiguredCoreServiceRuntime({env:{JARVIS_TEST_MODE:'0',JARVIS_CORE_ROOT:root,JARVIS_CORE_AUDIT_ROOT:join(root,'audit'),JARVIS_CORE_PORT:'0',JARVIS_CORE_ALLOWED_ROOTS:'workspace',JARVIS_CORE_WORKER_DAEMON_ENABLED:'0',JARVIS_CORE_WORKER_DAEMON_AUTOSTART:'0',JARVIS_CORE_REMOTE_PC_EXECUTION_ENABLED:'0',JARVIS_PERSONAL_IMPORT_ENABLED:'0',JARVIS_GOOGLE_SYNC_ENABLED:'0',JARVIS_PERSONAL_OPERATIONS_DB:join(root,'operations.sqlite'),JARVIS_CORE_MISSION_STORE_BACKEND:'sqlite',JARVIS_CORE_MISSION_AUTHORITY_ENABLED:'1',JARVIS_CORE_MISSION_AUTHORITY_EXPECTED_TOKEN:'0',JARVIS_CORE_ADMIN_TOKEN:'synthetic-browser-admin',JARVIS_LLM_INTENT:'0',JARVIS_LLM_PLANNER:'0',JARVIS_LLM_CONTENT:'0'},integrationVault:vault,integrationRegistry:new IntegrationConnectorRegistry(),modelProviderFetch:async url=>{calls++;if(String(url).includes('login.microsoftonline.com'))return Response.json({access_token:'synthetic.token',expires_in:3600,scope:'Mail.ReadBasic'});
 graphCalls++;const n=Number(new URL(String(url)).searchParams.get('$skip')??0)+1;
 return Response.json({value:pagesMode&&n===2?[]:[{id:pagesMode?'page-'+n:'one',subject:'<img src=x onerror=alert(1)> 합성 수집 자료 '+n}],...(pagesMode&&n<3?{'@odata.nextLink':'https://graph.microsoft.com/v1.0/me/messages?$select=id,subject,receivedDateTime&$skip='+n}:{})});}});
const binding={capabilityId:'source.collectMicrosoftMetadata',providerId:'microsoft-graph',accountRef:record.connectionId,deviceRef:null,scopes:['Mail.ReadBasic']};
function observe(){service.capabilityPackageRegistry.recordAvailability({...binding,codeVersion:service.capabilityPackageRegistry.availabilityFor(binding).codeVersion,permissionRevision:'synthetic-ui-v1',observedAt:new Date().toISOString(),accountStatus:'connected',observedAccountRef:record.connectionId,deviceStatus:'not-required',grantedScopes:binding.scopes,verificationLevel:'live-probe',evidenceRef:'synthetic-ui-no-real-account'});}
observe();
const control=httpServer((req,res)=>{if(req.url==='/restore'){record.status='credentials-stored-unverified';observe();if(pagesMode)service.personalOwnerSession.activate({durationMinutes:30,requestedBy:'synthetic-browser-fixture'});}if(req.url==='/revoke')record.status='revoked';res.setHeader('content-type','application/json');res.end(JSON.stringify({calls,graphCalls}));});await new Promise(r=>control.listen(0,'127.0.0.1',r));
const core=service.server;
await new Promise(r=>core.listen(0,'127.0.0.1',r));const reservation=createServer();await new Promise(r=>reservation.listen(0,'127.0.0.1',r));const port=reservation.address().port;await new Promise(r=>reservation.close(r));
const childEnv=Object.fromEntries(Object.entries(process.env).filter(([key])=>/^(PATH|PATHEXT|SYSTEMROOT|WINDIR|TEMP|TMP|USERPROFILE|APPDATA|LOCALAPPDATA|COMSPEC)$/iu.test(key)));
const ui=spawn(process.execPath,[packageDir?join(packageDir,'control-center-host/launch.mjs'):'scripts/dev-server.mjs'],{cwd:packageDir??process.cwd(),windowsHide:true,env:{...childEnv,PORT:String(port),JARVIS_CORE_API_URL:`http://127.0.0.1:${core.address().port}`,JARVIS_CORE_ADMIN_TOKEN:'synthetic-browser-admin'},stdio:['ignore','pipe','ignore']});
await new Promise((resolve,reject)=>{ui.stdout.once('data',resolve);ui.once('exit',code=>reject(Error('UI exit '+code)));});console.log(JSON.stringify({status:'ready',url:`http://127.0.0.1:${port}`,configuredService:true,packaged:packageDir!==null,control:`http://127.0.0.1:${control.address().port}`}));let stopped=false;
async function stop(){if(stopped)return;stopped=true;ui.kill();core.closeAllConnections();await new Promise(r=>control.close(r));await service.close();const target=resolve(root);if(!target.startsWith(resolve(tmpdir())+sep)||!target.includes('jarvis-ms-mission-ui-'))throw Error('FIXTURE_CLEANUP_PATH');await rm(target,{recursive:true,force:true});process.exit(0);}
process.stdin.once('data',stop);process.stdin.once('end',stop);
